sys_variable_value.value:
(function execute(inputs, outputs) {

    var riskRecord = inputs.risk_assessment_record;

    if (!riskRecord) {
        outputs.risk_score = 0;
        outputs.risk_level = 'critical';
        outputs.risk_explanation = 'Risk assessment record was not found.';
        return;
    }

    // Read existing risk assessment values
    var complianceScore = parseInt(
        riskRecord.getValue('compliance_score'), 10
    ) || 0;

    var missingDocuments = parseInt(
        riskRecord.getValue('missing_documents_count'), 10
    ) || 0;

    var daysRemaining = parseInt(
        riskRecord.getValue('days_remaining'), 10
    );

    // -----------------------------
    // 1. Compliance Risk: 0–50
    // -----------------------------
    var complianceRisk = 100 - complianceScore;

    // Convert the 0–100 compliance gap into a maximum of 50 points
    complianceRisk = Math.round(complianceRisk * 0.5);

    // -----------------------------
    // 2. Missing Documents Risk: 0–30
    // -----------------------------
    var documentRisk = missingDocuments * 10;

    if (documentRisk > 30) {
        documentRisk = 30;
    }

    // -----------------------------
    // 3. Deadline Risk: 0–20
    // -----------------------------
    var deadlineRisk = 0;

    if (isNaN(daysRemaining)) {
        deadlineRisk = 0;
    } else if (daysRemaining <= 6) {
        deadlineRisk = 20;
    } else if (daysRemaining <= 14) {
        deadlineRisk = 15;
    } else if (daysRemaining <= 30) {
        deadlineRisk = 10;
    } else {
        deadlineRisk = 0;
    }

    // -----------------------------
    // Final Risk Score: 0–100
    // -----------------------------
    var riskScore = complianceRisk + documentRisk + deadlineRisk;

    if (riskScore > 100) {
        riskScore = 100;
    }

    // -----------------------------
    // Risk Level
    // -----------------------------
    var riskLevel = 'low';

    if (riskScore >= 75) {
        riskLevel = 'critical';
    } else if (riskScore >= 50) {
        riskLevel = 'high';
    } else if (riskScore >= 25) {
        riskLevel = 'medium';
    }

    // -----------------------------
    // Explainable Reason
    // -----------------------------
    var reasons = [];

    reasons.push(
        'Compliance risk: ' + complianceRisk + ' points from a compliance score of ' +
        complianceScore + '.'
    );

    reasons.push(
        'Document risk: ' + documentRisk + ' points from ' +
        missingDocuments + ' missing document(s).'
    );

    if (!isNaN(daysRemaining)) {
        reasons.push(
            'Deadline risk: ' + deadlineRisk + ' points with ' +
            daysRemaining + ' day(s) remaining.'
        );
    } else {
        reasons.push(
            'Deadline risk: 0 points because remaining days are not available.'
        );
    }

    outputs.risk_score = riskScore;
    outputs.risk_level = riskLevel;
    outputs.risk_explanation =
        'Operational risk score: ' + riskScore + '/100 (' +
        riskLevel.toUpperCase() + '). ' +
        reasons.join(' ');

})(inputs, outputs);

