sys_variable_value.value:
(function execute(inputs, outputs) {

    var score = inputs.risk_score || 0;
    var level = inputs.risk_level || 'low';
    var explanation = inputs.risk_explanation || '';

    var response = '';

    response += 'Student Operational Risk Assessment\n\n';

    response += 'Risk Score: ' + score + '/100\n';
    response += 'Risk Level: ' + level.toUpperCase() + '\n\n';

    response += 'Why this score was assigned:\n';
    response += explanation + '\n\n';

    if (level == 'critical') {
        response += 'Priority: Immediate attention is recommended. ';
        response += 'Review missing documents, compliance issues, and upcoming deadlines.';
    }
    else if (level == 'high') {
        response += 'Priority: High attention is recommended. ';
        response += 'Resolve outstanding compliance and document issues as soon as possible.';
    }
    else if (level == 'medium') {
        response += 'Priority: Some attention is recommended. ';
        response += 'Review the outstanding items to prevent the risk from increasing.';
    }
    else {
        response += 'Priority: Current operational risk is low. ';
        response += 'Continue monitoring the visa case and compliance requirements.';
    }

    outputs.risk_assessment_response = response;

})(inputs, outputs);

